    {"calculate": "datum.value * 0 + (datum.tag == 'hit' ? 1 : 0)", "as": "indicator"}
  ],
  "mark": {"type": "bar", "tooltip": true},
  "encoding": {
    "x": {
      "field": "year",
      "type": "nominal",
      "axis": {"title": "Year"}
    },
    "y": {
      "aggregate": "sum",
      "field": "value",
      "type": "quantitative",
      "axis": {"title": "Count"}
    },
    "color": {
      "field": "category",
      "type": "nominal",
      "scale": {"scheme": "category20"},
      "legend": {"title": "Player"}
    },
    "column": {"field": "tag", "type": "nominal", "header": {"title": "Outcome"}}
  },
  "config": {
    "view": {"stroke": "transparent"},
    "axis": {"domainWidth": 1}
  }
}
